select case when orders.channel in ('web', 'store') then 'group_a' else 'other' end as channel_group, count(order_items.unit_price) as unit_price_count from order_items inner join products on products.id = order_items.product_id full outer join orders on order_items.order_id = orders.id group by case when orders.channel in ('web', 'store') then 'group_a' else 'other' end order by unit_price_count desc
